using System.Text.Json;

namespace GCFoundation.Common.Settings
{
    /// <summary>
    /// CDN versions and Subresource Integrity hashes shipped with GCFoundation.
    /// Loaded from <c>cdn-integrity.json</c>, which is generated by <c>npm run build:cdn-integrity</c> in GCFoundation.Components.
    /// </summary>
    public sealed class CdnIntegrityManifest
    {
        private const string ResourceName = "GCFoundation.Common.cdn-integrity.json";

        private static readonly JsonSerializerOptions SerializerOptions = new(JsonSerializerDefaults.Web);

        /// <summary>
        /// Gets the manifest embedded in this assembly.
        /// </summary>
        public static CdnIntegrityManifest Current { get; } = Load();

        /// <summary>
        /// Gets the Font Awesome version and hashes.
        /// </summary>
        public CdnPackageIntegrity FontAwesome { get; init; } = new();

        /// <summary>
        /// Gets the GC Design System components version and hashes.
        /// </summary>
        public CdnPackageIntegrity Gcds { get; init; } = new();

        /// <summary>
        /// Gets the GC Design System CSS Shortcuts version and hashes.
        /// </summary>
        public CdnPackageIntegrity GcdsCssShortcuts { get; init; } = new();

        private static CdnIntegrityManifest Load()
        {
            using var stream = typeof(CdnIntegrityManifest).Assembly.GetManifestResourceStream(ResourceName)
                ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' is missing from {typeof(CdnIntegrityManifest).Assembly.GetName().Name}.");

            return JsonSerializer.Deserialize<CdnIntegrityManifest>(stream, SerializerOptions)
                ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' is empty.");
        }
    }
}
